# Generate the solution and output as flat list
schedule = [[0]*35 for _ in range(5)]
for w in range(5):
    for a in range(5):
        for b in range(7):
            p = a * 7 + b
            schedule[w][p] = (b + w * a) % 7

# Flatten: entry w*35 + p = group of golfer p in week w
flat = []
for w in range(5):
    for p in range(35):
        flat.append(schedule[w][p])

print(flat)
print(f"Length: {len(flat)}")

# Double-check
def verify(flat):
    schedule = [[flat[w*35 + p] for p in range(35)] for w in range(5)]
    seen = set()
    for w in range(5):
        groups = [[] for _ in range(7)]
        for p in range(35):
            g = schedule[w][p]
            groups[g].append(p)
        for g in range(7):
            if len(groups[g]) != 5:
                return False, f"Week {w} group {g} size {len(groups[g])}"
            for i in range(5):
                for j in range(i+1, 5):
                    pair = (min(groups[g][i], groups[g][j]), max(groups[g][i], groups[g][j]))
                    if pair in seen:
                        return False, f"Pair {pair} repeats"
                    seen.add(pair)
    return True, "OK"

print(verify(flat))
